#!/usr/bin/env python3
import cadquery as cq
from pathlib import Path

SPEC = {'kind': 'extrusion', 'center': [-0.027300529999999996, -0.10274164499999999, -0.28609857], 'basis': [[0.0, -0.0, 1.0], [0.0, 1.0, 0.0], [-1.0, 0.0, 0.0]], 'axis': [1.0, 0.0, 0.0], 'zmin': -0.06558178, 'zmax': 0.06558178, 'profiles': [{'outer': [[-0.21183835, 0.07938237499999999], [-0.2088354, 0.085518795], [-0.20497073999999998, 0.091237475], [-0.19948708999999998, 0.098314005], [-0.19327229, 0.10481600499999999], [-0.18528184, 0.11223198499999999], [-0.17666468, 0.118969035], [-0.16598463, 0.126280595], [-0.15478234, 0.13278253499999998], [-0.14125599, 0.139597935], [-0.1271552, 0.14531661499999998], [-0.11151375, 0.150617495], [-0.09555896, 0.154168805], [-0.07866412, 0.156388325], [-0.06169094, 0.156884505], [-0.044639419999999985, 0.15599660499999998], [-0.02805789999999997, 0.15288923499999998], [-0.012573149999999977, 0.148136755], [0.0020237900000000253, 0.14124299499999998], [0.01502785000000001, 0.13299144499999999], [0.026282399999999984, 0.12257252499999999], [0.03539565, 0.11074350499999999], [0.04236772999999999, 0.097452155], [0.04709414000000001, 0.084291415], [0.04928758999999999, 0.07047785499999999], [0.04853025, 0.058439954999999995], [0.04604955999999999, 0.04632373499999999], [0.04312494, 0.03666202499999999], [0.04095759999999998, 0.027026524999999996], [0.040696469999999985, 0.020498384999999994], [0.04223713000000001, 0.014649134999999994], [0.045788439999999986, 0.01054944499999999], [0.05064538000000002, 0.007833764999999993], [0.058557479999999995, 0.006005864999999999], [0.07701912, 0.004308534999999988], [0.08699414, 0.0026634449999999865], [0.09733470999999999, -0.0002088950000000006], [0.1072053, -0.004360835000000007], [0.11650136, -0.00934831500000001], [0.12485740000000001, -0.015719785000000014], [0.13156827999999998, -0.023083555000000006], [0.14318839, -0.039795634999999996], [0.14940318000000002, -0.047812195], [0.15702805000000003, -0.05494090500000001], [0.16533187, -0.06141687500000001], [0.18254009, -0.073768105], [0.19068715000000003, -0.07977400500000001], [0.19828591, -0.086354385], [0.20465746, -0.09303921500000001], [0.20964494, -0.100716305], [0.21267398999999998, -0.109255145], [0.21379688000000002, -0.11865568500000001], [0.21390125, -0.127560075], [0.2127001, -0.13536773500000002], [0.21053275, -0.143070935], [0.20729472999999998, -0.14954687500000002], [0.2044746, -0.154064345], [0.20087107999999998, -0.156884505], [0.19823369000000002, -0.156832295], [0.19559637000000002, -0.15560497500000003], [0.19293281, -0.152784835], [0.19165855717025992, -0.15082998841038808], [0.18483797000000002, -0.14158251500000002], [0.18120828, -0.137404505], [0.17731753, -0.133800965], [0.17175552, -0.129936305], [0.16572353, -0.126907245], [0.15800204250277883, -0.12404743739707984], [0.14989927000000003, -0.122494205], [0.13995042000000002, -0.121971945], [0.12992319000000002, -0.12254643500000001], [0.11874703000000003, -0.123643155], [0.10757080000000002, -0.125105455], [0.08451340000000002, -0.128447855], [0.07179657, -0.129988495], [0.059053630000000024, -0.130928535], [0.044247780000000014, -0.131372455], [0.02946802999999998, -0.130980755], [0.015210600000000019, -0.130014595], [0.0011620199999999858, -0.12779500500000002], [-0.00990972000000001, -0.12487040500000002], [-0.020511420000000002, -0.12056182500000001], [-0.028867509999999985, -0.11620102500000001], [-0.03675345999999999, -0.11095237500000002], [-0.04307272000000001, -0.10609543500000002], [-0.04873915000000001, -0.100507335], [-0.05372666000000001, -0.094449225], [-0.05800912, -0.08781662500000001], [-0.062317700000000004, -0.07980005500000001], [-0.06594734999999999, -0.071391805], [-0.06962921999999999, -0.06199127500000001], [-0.07291938, -0.05240793500000002], [-0.07918642000000001, -0.032040135], [-0.08273773000000001, -0.02203898500000001], [-0.08715075, -0.012481795000000004], [-0.09271273, -0.003969085000000011], [-0.09916253, 0.003995284999999987], [-0.11208827999999998, 0.018409415], [-0.11754581, 0.025068124999999997], [-0.13543293, 0.048360574999999996], [-0.13937591, 0.05295635499999999], [-0.1432928, 0.05689935499999999], [-0.14765361, 0.06029401499999999], [-0.15284999999999999, 0.063531955], [-0.1584381, 0.06598658499999999], [-0.16478346, 0.06784059499999999], [-0.17136384999999998, 0.068441165], [-0.17841424, 0.06763164499999999], [-0.18567354, 0.06593434499999999], [-0.1922278, 0.06405423499999999], [-0.19867761, 0.06240914499999999], [-0.2028034, 0.061756324999999994], [-0.20700753, 0.061756324999999994], [-0.21011492999999998, 0.06280087499999999], [-0.21215171, 0.064393745], [-0.21350956, 0.067109425], [-0.21390125, 0.07032124499999999], [-0.21343121999999998, 0.074890955]], 'holes': []}], 'simplify_tolerance': 8.55605e-05, 'sketch_entity_count': 178}
OUT = Path(__file__).resolve().parent

def vec(v):
    return cq.Vector(float(v[0]), float(v[1]), float(v[2]))

def build():
    s = SPEC
    kind = s["kind"]
    B = s.get("basis")
    center = s.get("center")
    if kind == "extrusion":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = None
        height = s["zmax"] - s["zmin"]
        for profile in s["profiles"]:
            solid = cq.Workplane(plane).polyline(profile["outer"]).close().extrude(height)
            for hole in profile["holes"]:
                cutter = cq.Workplane(plane).polyline(hole).close().extrude(height)
                solid = solid.cut(cutter)
            result = solid if result is None else result.union(solid)
    elif kind == "multi_loft":
        def loft(track):
            wires = [cq.Wire.makePolygon([vec(p) for p in section], close=True) for section in track]
            return cq.Solid.makeLoft(wires, ruled=bool(s.get("ruled", True)))
        outer = [loft(track) for track in s["outer_tracks"]]
        # Keep disjoint solids as a legal STEP compound.  Global Boolean fusion
        # is unnecessary for training geometry and scales poorly with profiles.
        for track in s.get("hole_tracks", []):
            cutter = loft(track)
            cut_outer = []
            for solid in outer:
                try:
                    cut_outer.append(solid.cut(cutter))
                except Exception:
                    cut_outer.append(solid)
            outer = cut_outer
        result = outer[0] if len(outer) == 1 else cq.Compound.makeCompound(outer)
    elif kind == "box":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["mins"][0]*B[i][0] + s["mins"][1]*B[i][1] + s["mins"][2]*B[i][2] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        dx=s["maxs"][0]-s["mins"][0]; dy=s["maxs"][1]-s["mins"][1]; dz=s["maxs"][2]-s["mins"][2]
        result = cq.Workplane(plane).rect(dx,dy,centered=False).extrude(dz)
    elif kind == "cylinder":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = cq.Workplane(plane).circle(s["radius"]).extrude(s["zmax"]-s["zmin"])
    else:
        raise ValueError(kind)
    cq.exporters.export(result, str(OUT / "reconstructed.step"))
    cq.exporters.export(result, str(OUT / "reconstructed.stl"), tolerance=0.001, angularTolerance=0.05)
    return result

if __name__ == "__main__":
    build()
